/* 选一个适合讲解的景点名：优先当天的主题标题，过滤掉酒店/房型这类非景点 */
function pickGuideSpot(day,city){
  const bad=/酒店|大床房|双床房|房型|客栈|民宿|迎宾馆|宾馆|度假村|套房|标间/;
  let t=String(day&&day.title||'').replace(/^第?\s*\d+\s*天[\s:：·—\-]*/,'').trim();
  if(t&&!bad.test(t)) return t;
  const r=(day&&day.recommendations||[]).map(x=>x&&x.name).find(n=>n&&!bad.test(n));
  if(r) return String(r).split('-')[0].trim();
  const slot=[day&&day.morning,day&&day.afternoon,day&&day.evening].filter(Boolean).join(' ');
  return t||slot.slice(0,14)||city||'景点';
}
function renderAIPlan(d){
  const box=document.getElementById('ai-result');
  const powered=d.ai_powered?'<span class="ai-badge">✦ 真实 AI 生成</span>':'<span class="ai-badge" style="background:#d97706">本地推荐</span>';
  const notice=d.notice?`<div class="note" style="color:#b45309;margin-bottom:12px">${esc(d.notice)}</div>`:'';
  // 实时天气提示条（工具调用注入 prompt 的可视化凭证）
  let weatherHtml='';
  const wx=d.weather;
  if(wx&&wx.days&&wx.days.length){
    const chips=wx.days.map(x=>`<span class="wx-chip" style="display:inline-flex;flex-direction:column;align-items:center;gap:2px;padding:6px 10px;margin:3px 5px 0 0;border:1px solid ${x.bad?'#fcd34d':'#bae6fd'};border-radius:9px;background:${x.bad?'#fffbeb':'#f0f9ff'};font-size:12px;min-width:64px">
      <b style="color:${x.bad?'#b45309':'#0369a1'}">${esc(String(x.date||'').slice(5))}</b>
      <span>${x.bad?'🌧':'☀️'} ${esc(x.desc||'')}</span>
      <span style="color:var(--muted)">${x.tempMin!=null&&x.tempMax!=null?x.tempMin+'~'+x.tempMax+'℃':''}</span>
    </span>`).join('');
    const badNote=(wx.badDays&&wx.badDays.length)
      ?`<div style="margin-top:8px;color:#b45309;font-size:13px">🌧 检测到 <b>${wx.badDays.length}</b> 天有降雨/恶劣天气，已让 AI 把当天的户外景点替换为室内备选（博物馆、展馆、商圈等）。</div>`
      :`<div style="margin-top:8px;color:#0e7490;font-size:13px">☀️ 行程期间天气良好，已按晴天优先安排户外观景项目。</div>`;
    weatherHtml=`<div style="border:1px solid #bae6fd;background:linear-gradient(180deg,#f0f9ff,#fff);border-radius:12px;padding:12px 14px;margin-bottom:14px">
      <div style="font-weight:700;color:#0369a1;font-size:14px">🌤️ 已接入实时天气 · 智能调整行程 <span class="api-tag" style="background:#e0f2fe;color:#0369a1">实时数据注入</span></div>
      <div style="margin-top:6px">${chips}</div>${badNote}
      <div style="margin-top:6px;font-size:11px;color:var(--muted)">数据来源：${esc(wx.source||'实时天气 API')} · 生成时通过工具调用拉取并注入 AI</div>
    </div>`;
  }
  // 隐式需求识别卡片：AI 从原话里推断没说出口的约束，用户可一键采纳/忽略（关键节点主动确认）
  let needsHtml='';
  const needs=d.inferred_needs||[];
  if(needs.length){
    const needCards=needs.map((n,i)=>{
      const col=['#7c3aed','#0369a1','#b45309','#047857'][i%4];
      return `<div class="need-card" data-need="${i}" style="border-left:3px solid ${col};padding:10px 12px;margin:8px 0;background:#fff;border-radius:8px;border-top:1px solid #eef0ff;border-right:1px solid #eef0ff;border-bottom:1px solid #eef0ff">
        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <b style="color:${col};font-size:14px">✦ ${esc(n.need||'隐性需求')}</b>
          <span class="api-tag" style="background:#ede9fe;color:#6d28d9">隐式识别</span>
        </div>
        <div style="margin-top:6px;font-size:12.5px;line-height:1.7;color:#475569">
          <div>🔎 从你的描述「<b>${esc(n.from||'—')}</b>」推断</div>
          <div>💭 ${esc(n.reason||'—')}</div>
          <div>✅ 行程调整：${esc(n.adjusted||'—')}</div>
        </div>
        <div style="margin-top:8px;display:flex;gap:8px">
          <button class="btn sm need-accept" data-i="${i}" style="background:#7c3aed;color:#fff;padding:3px 12px;font-size:12px">✓ 采纳</button>
          <button class="btn sm ghost need-ignore" data-i="${i}" style="padding:3px 12px;font-size:12px">✗ 不用</button>
        </div>
      </div>`;
    }).join('');
    needsHtml=`<div class="card" style="border-color:#ddd6fe;background:linear-gradient(180deg,#faf8ff,#fff)" id="needs-card">
      <h2>🔍 AI 识别到的隐性需求 <span class="api-tag" style="background:#ede9fe;color:#6d28d9">可解释 · 从你的话里推断</span></h2>
      <p class="desc" style="margin:6px 0 10px">你没明说，AI 从描述里读出了这些约束，并已写进行程。如果判断有误，点「不用」即可忽略——不替你做主。</p>
      ${needCards}
      <div id="needs-feedback" style="font-size:12px;color:#6d28d9;margin-top:6px"></div>
    </div>`;
  }
  // 多人协作折中说明卡片（仅 group-plan 返回时渲染）
  let groupHtml='';
  if(d.is_group_plan){
    const comps=(d.compromises||[]).map((c,i)=>{
      const colors=['#be185d','#7c3aed','#0369a1','#b45309','#047857','#4338ca'];
      const col=colors[i%colors.length];
      return `<div class="comp-card" style="border-left:3px solid ${col}">
        <div class="comp-name" style="color:${col}">${esc(c.name||('同行者'+(i+1)))}</div>
        <div class="comp-line"><b style="color:#047857">✓ 保留</b><span>${esc(c.kept||'—')}</span></div>
        <div class="comp-line"><b style="color:#b45309">↔ 让步</b><span>${esc(c.gaveUp||'—')}</span></div>
        <div class="comp-line"><b style="color:#0369a1">✦ 换来</b><span>${esc(c.gained||'—')}</span></div>
      </div>`;
    }).join('');
    groupHtml=`<div class="card" style="border-color:#f9a8d4;background:linear-gradient(180deg,#fffafc,#fff)">
      <h2>🤝 多人折中方案 <span class="api-tag" style="background:#fce7f3;color:#be185d">AI 协商结果</span></h2>
      ${d.consensus?`<div class="consensus-box"><b>共同点</b><span>${esc(d.consensus)}</span></div>`:''}
      <div class="comp-grid">${comps||'<div class="empty">暂无折中说明</div>'}</div>
      ${d.balance_note?`<div class="note" style="margin-top:10px">⚖️ ${esc(d.balance_note)}</div>`:''}
    </div>`;
  }
  const recHtml=recs=>(recs||[]).filter(x=>x&&x.refId!=null).map(x=>
    `<span class="ai-rec" onclick="aiBuy(${x.refId},'${esc(x.type||'')}','${esc(x.name||'')}')">${esc(x.name||'商品')} ${x.price!=null?'¥'+Number(x.price).toFixed(0):''} →</span>`
  ).join('');
  let html=`<div class="card" style="border-color:#fcd34d">${notice}${weatherHtml}${needsHtml}${groupHtml}
    <h2>🗺️ ${esc(d.city||'')} ${esc(d.days||'')} 日行程 ${powered}</h2>
    <p style="color:var(--muted);margin:8px 0 4px">${esc(d.summary||'')}</p>
    <div style="margin-top:10px;font-size:13px">
      <span class="tag">💰 预估花费 ¥${Number(d.estimated_cost||0).toFixed(0)}</span>
      <span class="tag">🎯 预算 ¥${Number(d.budget||0).toFixed(0)}</span>
      ${d.tips?`<div style="margin-top:10px;color:#b45309">💡 ${esc(d.tips)}</div>`:''}
    </div>
    <div class="actions" style="margin-top:12px">
      <button class="btn sm poster-btn" onclick="makePoster()">📷 生成行程海报</button>
      <button class="btn sm ghost" onclick="syncPlanEverywhere()">↔ 同步城市到搜索 / 知识库 / 地图</button>
      <button class="btn sm ghost" onclick="searchCityProducts('${esc(d.city||'')}')">搜索该城市商品 →</button>
    </div></div>`;
  // 对话式微调：在现有行程基础上用大白话继续改
  const changes=d.changes?`<div class="note" style="color:#6d28d9;margin-bottom:10px">✦ 本次调整：${esc(d.changes)}</div>`:'';
  const changedSet=new Set(d.changed_days||[]);
  const chatLog=(window.__planChat||[]).map(m=>`<div class="refine-msg ${m.role}">${esc(m.text)}</div>`).join('');
  html+=`<div class="refine-box">
    <h3>💬 对话式微调 <span class="api-tag" style="background:#ede9fe;color:#6d28d9">AI 多轮</span></h3>
    <div class="rhint">对行程不满意？直接用大白话告诉 AI，比如「第二天太赶了换成轻松点」「我不吃海鲜，去掉海鲜餐厅」。AI 会在原行程基础上修改，并高亮改动的那天。</div>
    ${changes}
    <div class="refine-log" id="refine-log">${chatLog||'<div style="font-size:12px;color:var(--muted)">还没有调整对话，试试下面的快捷要求或直接输入</div>'}</div>
    <div class="refine-quick">
      <span onclick="quickRefine('第二天安排轻松一点')">第二天轻松点</span>
      <span onclick="quickRefine('去掉海鲜类的餐厅')">不吃海鲜</span>
      <span onclick="quickRefine('多安排一些拍照打卡的地方')">多些拍照点</span>
      <span onclick="quickRefine('整体预算再降低一些')">降低预算</span>
    </div>
    <div class="refine-input">
      <input id="refine-text" placeholder="输入修改要求，回车发送…" onkeydown="if(event.key==='Enter')aiRefine()">
      <button class="btn sm" id="btn-refine" style="background:#6d28d9;color:#fff" onclick="aiRefine()">调整行程</button>
    </div>
  </div>`;
  (d.days_plan||[]).forEach(day=>{
    const spotText=[day.title,day.morning,day.afternoon,day.evening].filter(Boolean).join(' ');
    const photo=spotPhoto(spotText, d.city||'', 'scenic');
    const hero=photo?`<img class="ai-day-photo" src="${photo}" alt="${esc(day.title||'')}" loading="lazy">`:'';
    const isChanged=changedSet.has(day.day)||changedSet.has(Number(day.day));
    const guideSpot=pickGuideSpot(day,d.city);
    html+=`<div class="ai-day${isChanged?' day-changed':''}"><h3>📅 ${esc(day.title||('第'+day.day+'天'))}${isChanged?'<span class="change-flag">已调整</span>':''}<button class="guide-mini" style="margin-left:auto" onclick="openGuide('${esc(guideSpot)}','${esc(d.city||'')}')">🎧 讲讲这天</button></h3>${hero}
      <div class="slot"><b>上午</b>${esc(day.morning||'自由活动')}</div>
      <div class="slot"><b>下午</b>${esc(day.afternoon||'')}</div>
      <div class="slot"><b>晚上</b>${esc(day.evening||'')}</div>
      <div>${recHtml(day.recommendations)}</div></div>`;
  });
  if((d.hotels||[]).length){
    html+=`<div class="card"><h2>🏨 推荐住宿</h2><div>${recHtml(d.hotels)}</div></div>`;
  }
  const refs=d.references||[];
  if(refs.length){
    html+=`<div class="card" style="border-color:#bbf7d0"><h2>📚 引用的攻略出处</h2><div class="tags">${refs.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><div class="note" style="margin-top:8px">本次行程参考了以上知识库攻略内容，来源可追溯。</div><button class="btn sm ghost" style="margin-top:8px" onclick="showKbForCity('${esc(d.city||'')}')">查看这些攻略 →</button></div>`;
  }
  // 一键把「完整行程对象」推送给地图，按天着色 + 时间轴可视化
  const spots=[];
  (d.days_plan||[]).forEach(day=>(day.recommendations||[]).forEach(x=>{if(x&&x.name&&!spots.includes(x.name))spots.push(x.name.split('-')[0]);}));
  const dayCount=(d.days_plan||[]).length;
  window.__lastPlan=d;   // 存完整对象，避免把大 JSON 塞进 onclick
  html+=`<div class="card" style="border-color:#c7d2fe;background:linear-gradient(180deg,#fafbff,#fff)">
    <h2>✦ 把这份行程画到地图上 <span class="api-tag" style="background:#eef0ff;color:#4f46e5">AI × 地图联动</span></h2>
    <p class="desc" style="margin:6px 0 10px">按 <b>${dayCount}</b> 天分色打点连线，生成每日时间轴、景点详情气泡与逐天聚焦视图；行程的时段安排、推荐商品、预算花费和攻略出处会一并同步到地图页。</p>
    <div class="tags" style="margin-bottom:10px">${(d.days_plan||[]).map((day,i)=>`<span class="tag" style="border-left:3px solid ${['#e11d48','#2563eb','#059669','#d97706','#7c3aed'][i%5]}">第${i+1}天 ${(day.recommendations||[]).length} 个点</span>`).join('')}</div>
    <div class="actions" style="margin-top:0">
      <button class="btn" style="background:#4f46e5" onclick="openPlanOnMap()">✦ 在地图上查看完整行程</button>
      ${spots.length?`<button class="btn sm ghost" onclick="sendPlanToMap(${JSON.stringify(spots.slice(0,8)).replace(/\"/g,'&quot;')},'${esc(d.city||'')}')">仅看简化线路</button>`:''}
    </div></div>`;
  html+='<div class="note">点击带价格的商品标签即可跳到下单流程，系统会自动带入商品参数。</div>';
  box.innerHTML=html;
  // 隐式需求：关键节点主动确认（采纳/忽略），轻量交互不替用户做主
  box.querySelectorAll('.need-accept,.need-ignore').forEach(btn=>{
    btn.onclick=()=>{
      const card=btn.closest('.need-card');
      const i=+btn.dataset.i, need=(d.inferred_needs||[])[i]||{};
      const accept=btn.classList.contains('need-accept');
      if(card){card.style.opacity=accept?'1':'.5';card.style.borderLeftColor=accept?'#047857':'#9ca3af';
        card.querySelectorAll('button').forEach(b=>b.disabled=true);}
      const fb=document.getElementById('needs-feedback');
      const done=box.querySelectorAll('.need-card button[disabled]').length;
      const total=box.querySelectorAll('.need-card').length;
      if(fb)fb.textContent=(accept?'✓ 已采纳「'+(need.need||'该需求')+'」，行程已按此调整':'✗ 已忽略「'+(need.need||'该需求')+'」')+'（'+done+'/'+total+' 项已确认）';
      toast(accept?'✓ 已采纳，行程保持该调整':'✗ 已忽略该项调整');
    };
  });
}
/* AI 推荐商品 → 跳到下单：refId 已是房型/票种/服务ID，直接构造 suggest 结果 */
async function aiBuy(refId,type,name){
  const typeMap={hotel:'hotel_room',scenic:'scenic_ticket',transfer:'transfer_service'};
  const ptype=typeMap[type]||type||'hotel_room';
  const item={productTypeCode:ptype,productId:+refId,productName:name,quantity:1};
  if(ptype==='hotel_room'){item.checkInDate=daysFromNow(6);item.checkOutDate=daysFromNow(8);}
  else {item.travelTime=daysFromNow(6)+' 09:00:00';}
  if(['flight_cabin','train_seat','bus_seat'].includes(ptype)){
    const r=await api('/api/v1/me/travelers',{params:{pageNo:1,pageSize:1},headers:{'X-User-Id':currentUid()}});
    const tid=r.data?.list?.[0]?.travelerId; if(tid)item.travelerIds=[tid];
  }
  setCtx({product:{name,refId:+refId,type:ptype,price:null},orderId:null,paymentNo:null,paid:false,refundId:null});
  trade={step:1,orderId:null,items:[],paymentNo:null,amount:null,
    preset:{ok:true,orderTypeCode:ptype,item,needsTraveler:false}};
  setFlow('trade'); switchPanel('trade'); renderTrade();
  document.getElementById('t-resp').innerHTML=`<div class="note" style="color:#1a7f37">已从 AI 行程带入：<b>${esc(name)}</b>。下单后订单与积分会自动同步到全站状态条。</div>`;
  toast('已从 AI 行程带入商品：'+name);
}
let aiChatBusy=false;
async function aiChat(){
  if(aiChatBusy)return;
  aiChatBusy=true;
  const btn=document.getElementById('btn-ai-chat'); if(btn)btn.disabled=true;
  const q=document.getElementById('ai-question').value.trim();
  const box=document.getElementById('ai-chat-answer');
  if(!q){box.innerHTML='<div class="empty">请输入问题</div>';aiChatBusy=false;if(btn)btn.disabled=false;return}
  const [aid,city]=document.getElementById('ai-city').value.split('|');
  const areaId=aid==='kb'?(KB_AREA[city]||2):+aid;
  const t0=Date.now();
  box.innerHTML='<div class="loading"><span class="spin"></span>AI 思考中… <b id="chat-elapsed">0</b> 秒</div>';
  const timer=setInterval(()=>{const el=document.getElementById('chat-elapsed');if(el)el.textContent=Math.round((Date.now()-t0)/1000);},1000);
  try{
    const r=await api('/api/ai/chat',{method:'POST',body:{message:q,areaId, city:city||''}});
    let srcHtml='';
    const srcs=r.data.kb_sources||[];
    if(srcs.length)srcHtml=`<div class="tags" style="margin-top:8px">${srcs.map(s=>`<span class="tag">📚 ${esc(s.source)}</span>`).join('')}</div>
      <div class="actions" style="margin-top:8px"><button class="btn sm ghost" onclick="showKbForCity('${esc(city||'')}')">在知识库查看来源 →</button></div>`;
    box.innerHTML=`<div class="card" style="margin:0;border-color:#fcd34d"><div style="display:flex;gap:8px;align-items:flex-start"><b>✦ AI：</b><div>${esc(r.data.answer||JSON.stringify(r.data))}</div></div>${srcHtml}</div>`;
  }catch(e){
    box.innerHTML=`<div class="empty">请求出错：${esc(e.message||String(e))}</div>`;
  }finally{
    aiChatBusy=false; if(btn)btn.disabled=false; clearInterval(timer);
  }
}

/* ==================== AI 对话式微调行程 ==================== */
let aiRefineBusy=false;
async function aiRefine(){
  if(aiRefineBusy)return;
  const inp=document.getElementById('refine-text');
  const msg=(inp?.value||'').trim();
  const plan=window.__lastPlan;
  if(!msg){toast('请输入修改要求');return;}
  if(!plan||!plan.days_plan){toast('请先生成一份行程');return;}
  aiRefineBusy=true;
  const btn=document.getElementById('btn-refine');if(btn)btn.disabled=true;
  if(inp)inp.value='';
  const chat=(window.__planChat||(window.__planChat=[]));
  chat.push({role:'user',text:msg});
  const log=document.getElementById('refine-log');
  if(log)log.innerHTML=chat.map(m=>`<div class="refine-msg ${m.role}">${esc(m.text)}</div>`).join('')+'<div class="refine-msg ai">正在调整…</div>';
  try{
    const r=await api('/api/ai/refine',{method:'POST',body:{
      plan, message:msg, city:plan.city||'',
      history:chat.slice(0,-1).map(m=>({role:m.role==='user'?'user':'assistant',content:m.text}))
    }});
    if(!r.ok){chat.push({role:'ai',text:'调整失败：'+JSON.stringify(r.data)});renderAIPlan(plan);return;}
    const d=r.data;
    // 微调接口不返回天气，沿用原行程的实时天气数据，保证天气条不消失
    if(plan.weather) d.weather=plan.weather;
    // 把 AI 的说明追加进对话（行程卡片本身会随 renderAIPlan 重建）
    chat.push({role:'ai',text:d.changes||'已按要求调整好行程'});
    applyPlanContext(d);
    renderAIPlan(d);
    // 若当前正显示地图，同步刷新为调整后的行程
    if(pendingPlan&&document.getElementById('panel-map')?.classList.contains('active')){
      pendingPlan=Object.assign({},d,{_uid:Date.now()+'_'+Math.random().toString(36).slice(2,7)});
      pushPlanToFrame();
    }
    toast('行程已调整'+(d.changes?'：'+d.changes:''));
  }catch(e){
    chat.push({role:'ai',text:'请求出错：'+(e.message||String(e))});renderAIPlan(plan);
  }finally{
    aiRefineBusy=false;if(btn)btn.disabled=false;
  }
}
function quickRefine(text){
  const inp=document.getElementById('refine-text');
  if(inp){inp.value=text;aiRefine();}
}

/* ==================== AI 随行导游（景点讲解） ==================== */
let guideBusy=false;
let guideCtx={spot:'',city:'',history:[]};
function openGuide(spot,city){
  if(!spot)return;
  guideCtx={spot,city:city||'',history:[]};
  const mask=document.getElementById('guide-mask');
  const drawer=document.getElementById('guide-drawer');
  const body=document.getElementById('guide-body');
  if(!mask||!drawer||!body)return;
  mask.classList.add('show');drawer.classList.add('show');
  const spotTag=`<div class="guide-spot">📍 ${esc(spot)}${city?' · '+esc(city):''}</div>`;
  body.innerHTML=spotTag+'<div class="loading" style="margin:18px 0"><span class="spin"></span>小云正在熟悉这个景点…</div>';
  guideCall('');
}
function closeGuide(){
  document.getElementById('guide-mask')?.classList.remove('show');
  document.getElementById('guide-drawer')?.classList.remove('show');
}
function renderGuideBody(){
  const body=document.getElementById('guide-body');if(!body)return;
  let html=`<div class="guide-spot">📍 ${esc(guideCtx.spot)}${guideCtx.city?' · '+esc(guideCtx.city):''}</div>`;
  const h=guideCtx.history||[];
  if(h.length){
    // history 存的是 [user,assistant] 成对；首条 user 是触发讲解的占位
    for(let i=0;i<h.length;i+=2){
      if(h[i]?.content)html+=`<div class="guide-msg u">${esc(h[i].content)}</div>`;
      if(h[i+1]?.content)html+=`<div class="guide-msg g">✦ ${esc(h[i+1].content)}</div>`;
    }
    const srcs=guideCtx.sources||[];
    if(srcs.length)html+=`<div class="guide-src">📚 讲解参考：${srcs.map(s=>esc(s.source)).filter((v,i,a)=>a.indexOf(v)===i).join('、')}</div>`;
  }
  body.innerHTML=html;body.scrollTop=body.scrollHeight;
}
async function guideCall(question){
  if(guideBusy)return;
  guideBusy=true;
  const body=document.getElementById('guide-body');
  try{
    const r=await api('/api/ai/guide',{method:'POST',body:{
      spot:guideCtx.spot,city:guideCtx.city,question:question||'',
      history:guideCtx.history
    }});
    const ans=r.data?.ok?r.data.answer:('讲解暂时不可用：'+(r.data?.answer||'未知错误'));
    guideCtx.sources=r.data?.kb_sources||[];
    // 成对记录，供重绘：user 问 + assistant 答
    guideCtx.history.push({role:'user',content:question||''});
    guideCtx.history.push({role:'assistant',content:ans});
    renderGuideBody();
  }catch(e){
    if(body)body.innerHTML=`<div class="guide-spot">📍 ${esc(guideCtx.spot)}</div><div class="guide-msg g">讲解服务出错：${esc(e.message||String(e))}</div>`;
  }finally{guideBusy=false;}
}
async function guideAsk(){
  if(guideBusy)return;
  const inp=document.getElementById('guide-input');
  const q=(inp?.value||'').trim();
  if(!q){toast('请输入想问的问题');return;}
  if(inp)inp.value='';
  const body=document.getElementById('guide-body');
  if(body)body.insertAdjacentHTML('beforeend',`<div class="guide-msg u">${esc(q)}</div>`);
  await guideCall(q);
}
