/* 统一面板切换 + 顶部流程条状态 */
let flowStage='search';
function setFlow(stage){
  flowStage=stage;
  const map={search:'search',trade:'trade',pay:'pay',refund:'refund'};
  const activePanel={search:'search',trade:'trade',pay:'trade',refund:'refund'}[stage]||stage;
  const order=['search','trade','pay','refund'];
  const cur=order.indexOf(stage);
  document.querySelectorAll('.flow-step').forEach(el=>{
    const s=el.dataset.fs, i=order.indexOf(s);
    el.classList.toggle('active',s===stage);
    el.classList.toggle('done',i<cur);
  });
  return activePanel;
}
function switchPanel(p){
  document.querySelectorAll('nav button').forEach(x=>x.classList.toggle('active',x.dataset.panel===p));
  document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));
  const el=document.getElementById('panel-'+p); if(el)el.classList.add('active');
  if(p==='trade')renderTrade();
  if(p==='overview')loadStats();
  if(p==='console')renderConsole();
  if(p==='member')loadMember();
  if(p==='refund'){loadRefundableItems();loadRefundList();}
  if(p==='guides'){loadGuides();loadMyBookings();}
  if(p==='kb')loadKbStats();
  if(p==='map'){
    renderMapCitySpots();
    // 面板刚变为可见，通知 iframe 重算尺寸并重绘（隐藏时容器宽高为 0 会导致建图失败）
    const f=document.getElementById('map-frame');
    if(f&&f.contentWindow)setTimeout(()=>{try{f.contentWindow.postMessage({type:'map-show'},'*');}catch(e){}},120);
  }
  window.scrollTo({top:0,behavior:'smooth'});
}
